        print("%-5s add note=%r rc=%d out=%r err=%r | reparse rc=%d note=%r same_as_printed=%s" % (
            name, note, p.returncode, out, p.stderr.decode().strip(), q.returncode, back,
            (out.rstrip("\n").split(" ",3)+[""])[3] == back if back is not None else None))
EOF
